###############################################################################
# app.R  —  INNOnet Tariff Simulator
#
# Loads pre-computed coefficients and baseline profiles from data/.
# Generated by R/02_estimate_models.R.
###############################################################################

library(shiny)
library(dplyr)
library(tidyr)
library(ggplot2)
library(plotly)
library(here)

# ---------------------------------------------------------------------------
# Data — loaded once at startup
# ---------------------------------------------------------------------------

# DiD estimates: the signal response is identified against the never-signalled
# control group (see R/02_estimate_models.R section 2), which nets out the
# endogenous demand that triggers the signal.
coefs_nb2  <- readRDS(here("data", "coefs_nb2_did.rds"))
coefs_nb1 <- readRDS(here("data", "coefs_nb1_did.rds"))
baseline  <- readRDS(here("data", "baseline_profiles.rds"))

# 15-min load values per subgroup (control group, post period) for a true load
# duration curve. Same source as `baseline` but not collapsed to the average
# day, so the curve's peak reflects actual peak timestamps. See
# R/02_estimate_models.R section 3b. Columns: region, subgroup_dim, subgroup_val, hour, load_kwh.
baseline_duration <- readRDS(here("data", "baseline_duration.rds"))

# Data-basis descriptor (period + household counts), written by 02_estimate_models.R
# so the dashboard text stays in sync with the analysis window.
sim_meta <- readRDS(here("data", "sim_meta.rds"))

# Minimum number of distinct days on which a signal must have occurred at an
# hour before that hour may be activated in the dashboard.
#
# The tariff windows are staggered across households, so an hour can carry a
# coefficient that rests on very few nights. NB1 low_tariff at 01:00-03:00 is
# the extreme case: 7 days only, yet the largest effect in the whole tool
# (+0.36 kW/household, driven by EV charging -- real, but far too thin to put
# in front of a user next to the well-identified midday hours).
#
# 30 sits inside a clean gap in the data: coverage per hour is either <= 24
# days or >= 50 days, nothing in between (see sim_meta$coverage, written by
# R/02_estimate_models.R section 3c). The surviving hours are exactly the designed
# windows -- NB2 11-14, NB1 HT 17-20, NB1 NT 11-14.
MIN_SIGNAL_DAYS <- 30

# Hours passing the coverage threshold. Falls back to "no restriction" when the
# model files predate sim_meta$coverage, so an older data/ still runs.
covered_hours <- function(reg, sig) {
  cv <- sim_meta$coverage
  if (is.null(cv)) return(NULL)
  cv |>
    filter(region == reg, signal_type == sig, n_days >= MIN_SIGNAL_DAYS) |>
    pull(hour)
}

# Keep only hours that BOTH have an estimate and rest on enough days.
restrict_to_covered <- function(hours, reg, sig) {
  cov <- covered_hours(reg, sig)
  if (is.null(cov)) hours else sort(intersect(hours, cov))
}

# Hours for which estimates exist (limits what the user can activate)
hours_af <- coefs_nb2  |> filter(signal_type == "exception_window")   |> pull(hour) |> unique() |> sort()
hours_af <- restrict_to_covered(hours_af, "NB2", "exception_window")

hour_label <- function(h) paste0(formatC(h, width = 2, flag = "0"), ":00")

# NB1: one tariff state per hour -> "off" / "ht" / "nt". Because each hour can
# hold only a single value, the same hour can never be HT and NT at once.
# Defaults follow the dominant signal observed in the data (NT midday, HT evening).
nb1_hours   <- 0:23
nb1_default <- setNames(rep("off", length(nb1_hours)), as.character(nb1_hours))
nb1_default[as.character(11:14)] <- "nt"   # Niedrigtarif: Mittag
nb1_default[as.character(17:20)] <- "ht"   # Hochtarif:  Abend

# Hours that actually have an HT / NT estimate. Off-window hours drop out of the
# models via collinearity (the signal never occurred there), so the matching
# radio option is shown but disabled (greyed) rather than removed -> the user
# still sees the full 0-23 grid and which hours simply offer no HT/NT.
nb1_ht_hours <- coefs_nb1 |>
  filter(signal_type == "high_tariff") |> pull(hour) |> unique() |>
  restrict_to_covered("NB1", "high_tariff")
nb1_nt_hours <- coefs_nb1 |>
  filter(signal_type == "low_tariff") |> pull(hour) |> unique() |>
  restrict_to_covered("NB1", "low_tariff")

# Effective defaults: never pre-select an option that has no estimate.
nb1_default_eff <- nb1_default
for (h in nb1_hours) {
  hc <- as.character(h)
  if (nb1_default_eff[[hc]] == "ht" && !(h %in% nb1_ht_hours)) {
    nb1_default_eff[[hc]] <- "off"
  }
  if (nb1_default_eff[[hc]] == "nt" && !(h %in% nb1_nt_hours)) {
    nb1_default_eff[[hc]] <- "off"
  }
}

# Value of a radio <input> tag, or NA for any other child node.
radio_value <- function(ch) {
  if (inherits(ch, "shiny.tag") && identical(ch$name, "input") &&
      !is.null(ch$attribs$value)) {
    ch$attribs$value
  } else {
    NA_character_
  }
}

# Walk a radioButtons tag tree and disable the option <input>s whose value is in
# `values`, greying the wrapping label so they read as inactive but stay visible.
disable_radio_options <- function(tag, values) {
  if (inherits(tag, "shiny.tag")) {
    if (identical(tag$name, "label")) {
      vals <- vapply(tag$children, radio_value, character(1))
      if (any(vals %in% values, na.rm = TRUE)) {
        tag$attribs$style <- "opacity:0.4; cursor:not-allowed;"
        tag$children <- lapply(tag$children, function(ch) {
          v <- radio_value(ch)
          if (!is.na(v) && v %in% values) ch$attribs$disabled <- "disabled"
          ch
        })
        return(tag)
      }
    }
    tag$children <- lapply(tag$children, disable_radio_options,
                           values = values)
  } else if (is.list(tag)) {
    tag <- lapply(tag, disable_radio_options, values = values)
  }
  tag
}

# One hour's tariff-state selector (used twice -> two-column layout in sidebar).
# HT and/or NT are greyed out when no estimate exists for that hour.
nb1_hour_radio <- function(h) {
  rb <- radioButtons(
    inputId  = paste0("nb1_h_", h),
    label    = hour_label(h),
    choices  = c("aus" = "off", "HT" = "ht", "NT" = "nt"),
    selected = nb1_default_eff[[as.character(h)]],
    inline   = TRUE
  )
  disable <- c(if (!(h %in% nb1_ht_hours)) "ht",
               if (!(h %in% nb1_nt_hours)) "nt")
  if (length(disable)) rb <- disable_radio_options(rb, disable)
  rb
}

# Shared plot styling: larger text and, importantly, wide legend keys so the
# dashed (Baseline) vs solid (Simuliert) lines are actually distinguishable.
sim_theme <- theme_minimal(base_size = 15) +
  theme(
    legend.position  = "bottom",
    legend.box       = "vertical",
    legend.key.width = unit(2.4, "cm"),
    legend.text      = element_text(size = 13),
    legend.spacing.y = unit(2, "pt"),
    plot.title       = element_text(face = "bold"),
    plot.margin      = margin(10, 18, 10, 10)
  )

# Force the line-type legend keys to render as bold, clearly visible lines.
linetype_guide <- guides(
  linetype = guide_legend(override.aes = list(linewidth = 1.1)))

# German display labels (data values stay English; only the plots are relabelled)
sub_labels <- c(
  "All"          = "Alle",
  "EV"           = "Mit E-Auto",
  "No EV"        = "Ohne E-Auto",
  "No PV"        = "Ohne PV",
  "PV only"      = "Nur PV",
  "PV + Storage" = "PV + Speicher",
  "Heat Pump"    = "Wärmepumpe",
  "No Heat Pump" = "Ohne Wärmepumpe"
)

# Baseline = without tariff signal, Simuliert = with simulated tariff.
kurve_linetypes <- c("Ohne Tarif" = "dashed", "Mit Tarif" = "solid")

# Sidebar choices, also used to label the CSV exports.
region_choices <- c(
  "Netzbetreiber 1 (NB 1) - HT/NT-Fenster"   = "NB1",
  "Netzbetreiber 2 (NB 2) - Ausnahmefenster" = "NB2"
)
subgroup_choices <- c(
  "Alle Haushalte" = "all",
  "E-Auto"         = "ev",
  "PV"             = "pv",
  "Heizung"        = "hp"
)

# CSV for German Excel: semicolon separator and decimal comma (write.csv2),
# UTF-8 with BOM so umlauts survive opening the file by double-click.
write_csv_de <- function(df, file) {
  con <- file(file, open = "w", encoding = "UTF-8")
  on.exit(close(con))
  writeLines("﻿", con, sep = "")
  utils::write.csv2(df, con, row.names = FALSE)
}

