# ---------------------------------------------------------------------------
# Server
# ---------------------------------------------------------------------------

server <- function(input, output, session) {

  # --- Household count for the selected region (data-basis note) ---
  output$region_n <- renderText({
    n <- sim_meta$n_households[[input$region]]
    paste0("n = ", n, " Haushalte gesamt im Auswertungszeitraum")
  })

  # --- Reset NB1 tariff windows to their defaults ---
  observeEvent(input$reset_nb1, {
    for (h in nb1_hours) {
      updateRadioButtons(session, paste0("nb1_h_", h),
                         selected = nb1_default_eff[[as.character(h)]])
    }
  })

  # --- Baseline for current region + subgroup + day type ---
  base_data <- reactive({
    d <- baseline
    if ("day_type" %in% names(d)) d <- filter(d, day_type == input$day_type)
    d |> filter(region == input$region, subgroup_dim == input$subgroup_dim)
  })

  # --- Estimated tariff effect per (subgroup, hour) for the active signal hours.
  # Shared by the hourly profile and the load-duration curve so both apply the
  # exact same effect. Columns: subgroup_val, hour, estimate, std_error. ---
  delta_data <- reactive({
    if (input$region == "NB2") {
      active_hours <- as.integer(input$sel_af)
      coefs_nb2 |>
        filter(subgroup_dim == input$subgroup_dim,
               signal_type  == "exception_window",
               hour         %in% active_hours) |>
        select(subgroup_val, hour, estimate, std_error)

    } else {
      # Read the per-hour radio state; an hour is HT, NT, or off — never both.
      sel <- vapply(nb1_hours, function(h) {
        v <- input[[paste0("nb1_h_", h)]]
        if (is.null(v)) "off" else v
      }, character(1))
      active_ht <- nb1_hours[sel == "ht"]
      active_nt <- nb1_hours[sel == "nt"]

      bind_rows(
        coefs_nb1 |>
          filter(subgroup_dim == input$subgroup_dim,
                 signal_type  == "high_tariff",
                 hour         %in% active_ht),
        coefs_nb1 |>
          filter(subgroup_dim == input$subgroup_dim,
                 signal_type  == "low_tariff",
                 hour         %in% active_nt)
      ) |>
        group_by(subgroup_val, hour) |>
        # Independent signals add in variance, so SEs combine in quadrature.
        summarise(estimate  = sum(estimate),
                  std_error = sqrt(sum(std_error^2)),
                  .groups   = "drop")
    }
  })

  # --- Apply simulation: add estimated effects for selected signal hours ---
  sim_data <- reactive({
    base_data() |>
      left_join(delta_data(), by = c("subgroup_val", "hour")) |>
      mutate(
        estimate      = replace_na(estimate, 0),
        std_error     = replace_na(std_error, 0),
        sim_kwh       = mean_kwh + estimate,
        # 95%-CI of the simulated curve from the coefficient SE; inactive
        # hours have estimate = SE = 0, so the band collapses to the line.
        sim_low       = sim_kwh - 1.96 * std_error,
        sim_high      = sim_kwh + 1.96 * std_error
      )
  })

  # --- Simulation on the 15-min series (Dauerlinie + Kennzahlen) ---
  # Same effect as sim_data, but applied to every 15-min slot instead of the
  # average-day profile, so peak/consumption metrics match the duration curve.
  dur_sim <- reactive({
    d <- baseline_duration
    if ("day_type" %in% names(d)) d <- filter(d, day_type == input$day_type)
    d |>
      filter(region       == input$region,
             subgroup_dim == input$subgroup_dim) |>
      left_join(delta_data(), by = c("subgroup_val", "hour")) |>
      mutate(estimate = replace_na(estimate, 0),
             sim_kwh  = load_kwh + estimate)
  })

  # --- Stable Y-range for the load profile ---
  # Baseline range spans ALL day_types → stable when switching Werktag /
  # Wochenende / Gesamt. Padding is 30 % of the baseline spread (same as
  # the original formula). Max positive tariff effect is added on top of
  # the upper bound WITHOUT re-padding so the "Mit Tarif" curve never clips.
  y_range_profile <- reactive({
    all_kw <- baseline |>
      filter(region == input$region, subgroup_dim == input$subgroup_dim) |>
      left_join(delta_data(), by = c("subgroup_val", "hour")) |>
      mutate(estimate = replace_na(estimate, 0),
             base_kw  = mean_kwh * 4,
             sim_kw   = (mean_kwh + estimate) * 4) |>
      (\(d) c(d$base_kw, d$sim_kw))()

    rng <- range(all_kw, na.rm = TRUE)
    pad <- diff(rng) * 0.05
    c(max(0, rng[1] - pad), rng[2] + pad)
  })

  # --- Per-hour tariff state, for the hover tooltips ---
  # NB2: the exception window is on/off per hour; NB1: off / HT / NT per hour.
  hour_tarif <- reactive({
    if (input$region == "NB2") {
      active <- as.integer(input$sel_af)
      setNames(ifelse(nb1_hours %in% active, "Ausnahmefenster", "aus"),
               as.character(nb1_hours))
    } else {
      sel <- vapply(nb1_hours, function(h) {
        v <- input[[paste0("nb1_h_", h)]]
        if (is.null(v)) "off" else v
      }, character(1))
      setNames(recode(sel, "off" = "aus", "ht" = "HT", "nt" = "NT"),
               as.character(nb1_hours))
    }
  })

  # --- Current selection, prepended to every CSV export so a downloaded file
  # stays interpretable on its own. ---
  export_settings <- reactive({
    tarif  <- hour_tarif()
    active <- tarif[tarif != "aus"]
    list(
      Region           = names(region_choices)[region_choices == input$region],
      Vergleichsgruppe = names(subgroup_choices)[subgroup_choices == input$subgroup_dim],
      Tagestyp         = input$day_type,
      Tariffenster     = if (length(active)) {
        paste(hour_label(as.integer(names(active))), active, collapse = ", ")
      } else "keine",
      Zeitraum         = paste(sim_meta$period_from, "bis", sim_meta$period_to)
    )
  })

  export_name <- function(what) {
    paste0("tarifsimulator_", what, "_", input$region, "_", Sys.Date(), ".csv")
  }

  output$dl_profile <- downloadHandler(
    filename = function() export_name("lastprofil"),
    content  = function(file) {
      tarif <- hour_tarif()
      sim_data() |>
        transmute(
          Subgruppe              = recode(subgroup_val, !!!sub_labels),
          Stunde                 = hour_label(hour),
          Tarif                  = unname(tarif[as.character(hour)]),
          `Last ohne Tarif (kW)` = mean_kwh * 4,
          `Last mit Tarif (kW)`  = sim_kwh * 4,
          `Effekt (kW)`          = estimate * 4,
          `KI 95% unten (kW)`    = sim_low * 4,
          `KI 95% oben (kW)`     = sim_high * 4
        ) |>
        mutate(!!!export_settings(), .before = 1) |>
        write_csv_de(file)
    }
  )

  output$dl_dauerlinie <- downloadHandler(
    filename = function() export_name("dauerlinie"),
    content  = function(file) {
      dauer_data() |>
        transmute(
          Subgruppe              = recode(subgroup_val, !!!sub_labels),
          `Anteil der Zeit (%)`  = rank_pct,
          `Last ohne Tarif (kW)` = ohne_kw,
          `Last mit Tarif (kW)`  = mit_kw
        ) |>
        mutate(!!!export_settings(), .before = 1) |>
        write_csv_de(file)
    }
  )

  output$dl_metrics <- downloadHandler(
    filename = function() export_name("kennzahlen"),
    content  = function(file) {
      metrics_num() |>
        transmute(
          Subgruppe,
          `Peak ohne Tarif (kW)`              = peak_ohne,
          `Peak mit Tarif (kW)`               = peak_mit,
          `Delta Peak (kW)`                   = peak_mit - peak_ohne,
          `Delta Peak (%)`                    = 100 * (peak_mit - peak_ohne) / peak_ohne,
          `Ø täglicher Netzbezug ohne Tarif (kWh)` = avg_ohne,
          `Ø täglicher Netzbezug mit Tarif (kWh)`  = avg_mit
        ) |>
        mutate(!!!export_settings(), .before = 1) |>
        write_csv_de(file)
    }
  )

  # --- Hourly load profile (interactive: hover shows hour, tariff, load) ---
  output$plot_profile <- renderPlotly({
    tarif_tbl <- data.frame(hour  = nb1_hours,
                            tarif = unname(hour_tarif()),
                            stringsAsFactors = FALSE)

    d <- sim_data() |>
      pivot_longer(c(mean_kwh, sim_kwh),
                   names_to  = "Kurve",
                   values_to = "kwh") |>
      mutate(Kurve = recode(Kurve,
                            "mean_kwh" = "Ohne Tarif",
                            "sim_kwh"  = "Mit Tarif"),
             Kurve = factor(Kurve, levels = names(kurve_linetypes)),
             kw    = kwh * 4,                # kWh/15min -> kW (mittlere Last)
             # German subgroup labels up front, so the plotly legend and the
             # trace hover use them too (ggplotly ignores scale `labels`).
             subgroup_val = recode(subgroup_val, !!!sub_labels)) |>
      left_join(tarif_tbl, by = "hour") |>
      mutate(tooltip = paste0(
        subgroup_val, " - ", Kurve,
        "<br>Stunde: ", hour_label(hour),
        ifelse(Kurve == "Mit Tarif", paste0("<br>Tarif: ", tarif), ""),
        "<br>Ø Last: ", sprintf("%.3f", kw), " kW"))

    # Y-range is anchored to the "Gesamt" baseline so the axis stays fixed when
    # switching between Werktag / Wochenende / Gesamt or toggling tariff hours.
    y_rng <- y_range_profile()

    p <- ggplot(d, aes(hour, kw, colour = subgroup_val, linetype = Kurve,
                       group = interaction(subgroup_val, Kurve)))

    # Optional: 95%-CI-Band der "Mit Tarif"-Kurve aus der Unsicherheit der
    # Koeffizienten; sim_low/sim_high sind in kWh/15min. Bewusst OHNE `text`-
    # Aesthetik: ein globales text-Mapping, das die ribbon-Daten nicht haben,
    # bringt ggplotly zum Absturz (leerer Plot). Der Hover-Text liegt deshalb
    # nur auf den Linien-/Punkt-Ebenen.
    if (isTRUE(input$show_ci)) {
      ci <- sim_data() |>
        mutate(low_kw  = sim_low  * 4,
               high_kw = sim_high * 4,
               subgroup_val = recode(subgroup_val, !!!sub_labels))
      p <- p +
        geom_ribbon(data = ci,
                    aes(hour, ymin = low_kw, ymax = high_kw,
                        fill = subgroup_val),
                    inherit.aes = FALSE, alpha = 0.15) +
        scale_fill_brewer(palette = "Set1", guide = "none")
    }

    # `text` ist ein plotly-Hover-Aesthetic, das ggplot2 nicht kennt und schon
    # beim Hinzufuegen der Layer mit "Ignoring unknown aesthetics: text" quittiert
    # -> die Geom-Konstruktion gezielt stumm schalten.
    p <- suppressWarnings(p +
      geom_line(aes(text = tooltip), linewidth = 0.6) +
      geom_point(aes(text = tooltip), size = 0.8) +   # hover targets per hour
      scale_x_continuous(breaks = seq(0, 22, 2),
                         labels = paste0(seq(0, 22, 2), "h")) +
      scale_linetype_manual(values = kurve_linetypes) +
      scale_colour_brewer(palette = "Set1", name = NULL) +
      labs(x = NULL, y = "Ø Last (kW)",
           linetype = NULL, title = "Stündliches Lastprofil") +
      sim_theme + linetype_guide)

    gp <- ggplotly(p, tooltip = "text")

    # ggplotly verschmilzt Farbe (Untergruppe) und Linientyp (Kurve) zu
    # kombinierten Eintraegen wie "(Ohne Tarif,Nur PV)". Statt dessen die
    # automatischen Eintraege ausblenden und zwei kompakte Legendenbloecke
    # selbst bauen: ein Farbeintrag je Untergruppe + ein Linienstil je Kurve.
    for (i in seq_along(gp$x$data)) gp$x$data[[i]]$showlegend <- FALSE

    subs <- if (is.factor(d$subgroup_val)) levels(droplevels(d$subgroup_val))
            else sort(unique(as.character(d$subgroup_val)))
    # gleiche Set1-Palette wie scale_colour_brewer (clamp auf min. 3 Farben)
    sub_cols <- RColorBrewer::brewer.pal(max(3L, length(subs)), "Set1")[seq_along(subs)]

    # Dummy-Traces als Legende: eine Null-Laengen-Linie (zwei identische
    # Punkte) zeichnet nichts, erzeugt aber einen Legendeneintrag. Ein
    # einzelner NA-Punkt wuerde dagegen aus der Legende fallen.
    xa <- c(nb1_hours[1], nb1_hours[1])
    # Farb-Legende: ein Eintrag je Untergruppe
    for (k in seq_along(subs)) {
      gp <- add_trace(gp, x = xa, y = c(0, 0), type = "scatter",
                      mode = "lines", inherit = FALSE,
                      line = list(color = sub_cols[k], width = 2),
                      name = subs[k], legendgroup = "sub",
                      hoverinfo = "skip", showlegend = TRUE)
    }
    # Linienstil-Legende: gestrichelt = Ohne Tarif, durchgezogen = Mit Tarif
    # (schwarz; "black" ist gueltiges CSS, R-Namen wie "grey30" greifen nicht)
    kurve_dash <- c("Ohne Tarif" = "dash", "Mit Tarif" = "solid")
    for (nm in names(kurve_dash)) {
      gp <- add_trace(gp, x = xa, y = c(0, 0), type = "scatter",
                      mode = "lines", inherit = FALSE,
                      line = list(color = "black", width = 2, dash = kurve_dash[[nm]]),
                      name = nm, legendgroup = "kurve",
                      hoverinfo = "skip", showlegend = TRUE)
    }

    dtick_val <- if (diff(y_rng) <= 0.6) 0.05 else 0.1

    gp |>
      layout(legend = list(orientation = "h", y = -0.12),
             yaxis  = list(range    = y_rng,   autorange = FALSE,
                           tickmode = "linear", tick0     = 0,
                           dtick    = dtick_val),
             margin = list(t = 50))
  })

  # --- Difference bar chart ---
  output$plot_diff <- renderPlot({
    d <- sim_data() |>
      mutate(delta      = (sim_kwh  - mean_kwh) * 4,   # kWh/15min -> kW
             delta_low  = (sim_low  - mean_kwh) * 4,   # = delta - 1.96*SE*4
             delta_high = (sim_high - mean_kwh) * 4)   # = delta + 1.96*SE*4

    # Shared dodge so the optional error bars line up with their bars even with
    # several subgroups (3 PV levels). Same 95%-CI source as the profile band.
    dodge <- position_dodge(width = 0.9)

    p <- ggplot(d, aes(hour, delta, fill = subgroup_val)) +
      geom_col(position = dodge) +
      geom_hline(yintercept = 0, linetype = "dashed", colour = "grey50") +
      scale_x_continuous(breaks = seq(0, 23, 3),
                         labels = paste0(seq(0, 23, 3), "h")) +
      scale_fill_brewer(palette = "Set1", name = NULL, labels = sub_labels) +
      labs(x = NULL, y = "Effekt (kW)",
           title    = "Geschätzter Tarifeffekt je Stunde",
           subtitle = "> 0: mehr Netzbezug mit Tarif · < 0: weniger") +
      sim_theme

    # Toggled by the same checkbox as the profile band.
    if (isTRUE(input$show_ci)) {
      p <- p + geom_errorbar(aes(ymin = delta_low, ymax = delta_high),
                             position = dodge, width = 0.5,
                             colour = "grey30", linewidth = 0.3)
    }
    p
  })

  # --- Dauerlinie (Ø Last je Haushalt) ---
  # Built from the full 15-min series (baseline_duration), NOT the average-day
  # profile: the hourly tariff effect is broadcast onto every 15-min slot in an
  # active hour, then each curve is sorted descending. The peak (left edge) is
  # therefore a real peak timestamp, not a daily mean.
  #
  # load_kwh is the mean per household per 15 min, so * 4 -> mean kW per
  # household. The legend carries each group's control-group household count.
  # Interactive (plotly) so the curve can be zoomed/panned.
  # Sorted curves per subgroup, shared by the plot and the CSV export.
  # Exceedance convention: the i-th largest value is reached/exceeded in i/n of
  # the time, so the peak sits at ~100/n %, not at exactly 0 %.
  dauer_data <- reactive({
    dur_sim() |>
      group_by(subgroup_val) |>
      reframe(
        rank_pct = seq_len(n()) / n() * 100,
        ohne_kw  = sort(load_kwh, decreasing = TRUE) * 4,
        mit_kw   = sort(sim_kwh,  decreasing = TRUE) * 4
      )
  })

  output$plot_dauerlinie <- renderPlotly({
    # Legend labels: German subgroup name + control-group household count, so a
    # small group (e.g. PV only) is visibly less precise.
    ncur <- sim_meta$n_by_group |>
      filter(region == input$region, subgroup_dim == input$subgroup_dim)
    lab_map <- setNames(
      recode(ncur$subgroup_val, !!!sub_labels),
      ncur$subgroup_val
    )

    dl <- dauer_data() |>
      pivot_longer(c(ohne_kw, mit_kw),
                   names_to  = "Kurve",
                   values_to = "kw") |>
      mutate(Kurve = factor(recode(Kurve, "ohne_kw" = "Ohne Tarif",
                                          "mit_kw"  = "Mit Tarif"),
                            levels = names(kurve_linetypes)),
             # Read cumulatively: "in X % der Zeit ist die Last >= Y kW".
             # Below 1 % show "< 1 %" instead of a rounded "0 %", which would
             # misleadingly read as "never".
             pct_lab = ifelse(rank_pct < 1, "< 1", sprintf("%.0f", rank_pct)),
             tooltip = paste0(
               recode(subgroup_val, !!!lab_map), " - ", Kurve,
               "<br>Last ≥ ", sprintf("%.2f", kw), " kW",
               "<br>in ", pct_lab, " % der Zeit"))

    # `text` is a plotly-only hover aesthetic; ggplot warns about it -> silence.
    p <- suppressWarnings(
      ggplot(dl, aes(rank_pct, kw, colour = subgroup_val, linetype = Kurve,
                     group = interaction(subgroup_val, Kurve))) +
        geom_line(aes(text = tooltip), linewidth = 0.7) +
        scale_linetype_manual(values = kurve_linetypes) +
        scale_colour_brewer(palette = "Set1", name = NULL, labels = lab_map) +
        labs(x = "Anteil der Zeit (%)", y = "Ø Last je Haushalt (kW)",
             linetype = NULL, title = "Dauerlinie") +
        sim_theme + linetype_guide)

    gp <- ggplotly(p, tooltip = "text")

    # As in the profile plot: ggplotly merges colour (subgroup) and linetype
    # (Kurve) into combined entries -> hide the automatic ones and rebuild two
    # compact legend blocks (one colour per subgroup + one line style per Kurve).
    for (i in seq_along(gp$x$data)) gp$x$data[[i]]$showlegend <- FALSE

    subs <- sort(unique(as.character(dl$subgroup_val)))
    sub_cols <- RColorBrewer::brewer.pal(max(3L, length(subs)), "Set1")[seq_along(subs)]

    # Zero-length dummy traces: draw nothing but create a legend entry.
    for (k in seq_along(subs)) {
      gp <- add_trace(gp, x = c(0, 0), y = c(0, 0), type = "scatter",
                      mode = "lines", inherit = FALSE,
                      line = list(color = sub_cols[k], width = 1.5),
                      name = lab_map[[subs[k]]], legendgroup = "sub",
                      hoverinfo = "skip", showlegend = TRUE)
    }
    kurve_dash <- c("Ohne Tarif" = "dash", "Mit Tarif" = "solid")
    for (nm in names(kurve_dash)) {
      gp <- add_trace(gp, x = c(0, 0), y = c(0, 0), type = "scatter",
                      mode = "lines", inherit = FALSE,
                      line = list(color = "black", width = 1.5, dash = kurve_dash[[nm]]),
                      name = nm, legendgroup = "kurve",
                      hoverinfo = "skip", showlegend = TRUE)
    }

    gp |>
      layout(
        # Smaller, centred, lower legend so the two blocks don't crowd the
        # x-axis title.
        legend = list(orientation = "h", x = 0.5, xanchor = "center",
                      y = -0.2, font = list(size = 11)),
        # Force regular 0.5 kW ticks: ggplotly otherwise pins its own tickvals,
        # so dtick alone is ignored -> tickmode = "linear" is required.
        yaxis  = list(tickmode = "linear", tick0 = 0, dtick = 0.5,
                      rangemode = "tozero"),
        margin = list(t = 50, b = 95))
  })

  # --- Metrics table ---
  # All per household, computed from the 15-min series so they match the
  # Dauerlinie: Peak = highest 15-min power (kWh/15min * 4 -> kW); daily grid
  # import = mean 15-min load * 96 slots/day -> kWh/day.
  # Unrounded metrics per subgroup, shared by the table and the CSV export.
  metrics_num <- reactive({
    dur_sim() |>
      mutate(Subgruppe = recode(subgroup_val, !!!sub_labels)) |>
      group_by(Subgruppe) |>
      summarise(
        peak_ohne = max(load_kwh) * 4,
        peak_mit  = max(sim_kwh)  * 4,
        avg_ohne  = mean(load_kwh) * 96,
        avg_mit   = mean(sim_kwh)  * 96,
        .groups = "drop"
      )
  })

  output$tbl_metrics <- renderTable({
    metric_order <- c(
      "Peak Ohne Tarif (kW)", "Peak Mit Tarif (kW)",
      "Δ Peak (kW)", "Δ Peak (%)",
      "Ø täglicher Netzbezug Ohne Tarif (kWh)", "Ø täglicher Netzbezug Mit Tarif (kWh)"
    )

    metrics_num() |>
      mutate(
        # Format as character before pivoting so each metric keeps its own
        # decimal places (2 for kW/kWh, 1 for %).
        `Peak Ohne Tarif (kW)`              = sprintf("%.2f", round(peak_ohne, 2)),
        `Peak Mit Tarif (kW)`               = sprintf("%.2f", round(peak_mit,  2)),
        `Δ Peak (kW)`                       = sprintf("%.1f", round(peak_mit, 1) - round(peak_ohne, 1)),
        `Δ Peak (%)`                        = sprintf("%.1f", round(
          100 * (round(peak_mit, 2) - round(peak_ohne, 2)) / round(peak_ohne, 2), 1)),
        `Ø täglicher Netzbezug Ohne Tarif (kWh)` = sprintf("%.2f", round(avg_ohne, 2)),
        `Ø täglicher Netzbezug Mit Tarif (kWh)`  = sprintf("%.2f", round(avg_mit,  2))
      ) |>
      select(-peak_ohne, -peak_mit, -avg_ohne, -avg_mit) |>
      pivot_longer(-Subgruppe, names_to = "Kennzahl", values_to = "Wert") |>
      mutate(Kennzahl = factor(Kennzahl, levels = metric_order)) |>
      arrange(Kennzahl) |>
      pivot_wider(names_from = Subgruppe, values_from = Wert)
  }, striped = TRUE, hover = TRUE, width = "100%")
}

shinyApp(ui, server)
